export type ServiceTable = {
  headers: string[];
  rows: string[][];
};

export type ServiceBlock = {
  heading?: string;
  level?: 2 | 3;
  paragraphs?: string[];
  items?: string[];
  table?: ServiceTable;
};

export type Service = {
  slug: string;
  num: string;
  title: string;
  shortDesc: string;
  heroHeading: string;
  intro: string[];
  seoTitle: string;
  seoDescription: string;
  forWhoHeading: string;
  forWho: string[];
  deliverablesHeading: string;
  deliverables: string[];
  processHeading: string;
  process: string[];
  /** Extra sections in document order (between deliverables and process, or after process). */
  beforeProcess: ServiceBlock[];
  afterProcess: ServiceBlock[];
  faq: { q: string; a: string }[];
  /** @deprecated alias kept for search/filter compatibility */
  fullDesc: string;
};

export type ServicesOverview = {
  title: string;
  heroHeading: string;
  intro: string[];
  criteriaHeading: string;
  criteria: string[];
  outputsHeading: string;
  comparisonHeading: string;
  comparisonTable: ServiceTable;
  guideHeading: string;
  guideTable: ServiceTable;
  budgetOrderHeading: string;
  budgetOrder: string[];
  budgetNote: string;
  tipsHeading: string;
  tips: string[];
  ctaNote: string;
  faq: { q: string; a: string }[];
  seoTitle: string;
  seoDescription: string;
};


